<script lang="ts">
 import {invalidateAll} from '$app/navigation';import {page} from '$app/state';import {saveDraft} from '$lib/offline';import Icon from './Icon.svelte';
 let {model,t,tenantId,userId,role,lang='de',timezone='Europe/Berlin'}:{model:Record<string,any[]>;t:(key:string)=>string;tenantId:string;userId:string;role:string;lang?:string;timezone?:string}=$props();let message=$state(''),busy=$state(false),status=$state('active'),search=$state(''),limit=$state(6);
 let tasks=$derived(model.tasks.filter(task=>status==='all'||status==='active'?status==='all'||task.status!=='done':task.status===status).filter(task=>!search||(task.title+' '+task.description).toLowerCase().includes(search.toLowerCase())).filter(task=>!page.url.searchParams.get('task')||task.id===page.url.searchParams.get('task')));
 $effect(()=>{void status;void search;limit=6;});
 async function update(task:Record<string,any>,checklist:any[],next=task.status){if(busy)return;busy=true;message='';const command={type:'task_update',task_id:task.id,expected_version:task.version,checklist,status:next};try{if(!navigator.onLine){await saveDraft(tenantId,command);message=t('draftSaved');return;}const res=await fetch('/api/commands',{method:'POST',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify(command)});const result=await res.json();message=res.ok?t('saved'):result.message==='VERSION_CONFLICT'?t('conflict'):t(result.message);if(res.ok)await invalidateAll();}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
</script>
<section class="card task-section"><div class="task-header"><h2>{t('tasks')} <span class="pill">{tasks.length}</span></h2><label><span class="sr-only">{t('search')}</span><input type="search" bind:value={search} placeholder={t('search')}/></label></div><div class="task-filters" role="group" aria-label={t('status')}>{#each ['active','doing','done','all'] as value}<button class:selected={status===value} aria-pressed={status===value} onclick={()=>status=value}>{t(value)}</button>{/each}</div><div class="task-grid">{#each tasks.slice(0,limit) as task}{@const editable=['owner','oenologist','office'].includes(role)||task.assignee_id===userId||task.created_by===userId}{@const overdue=task.status!=='done'&&task.due_at&&Date.parse(task.due_at)<Date.now()}<article class:overdue><div class="task-meta"><span class={'pill '+(task.status==='done'?'good':task.status==='doing'?'info':'warning')}>{t(task.status)}</span>{#if overdue}<span class="due overdue-text"><Icon name="alert" size={13}/>{t('overdue')}</span>{/if}</div><h3>{task.title}</h3>{#if task.description}<details class="description"><summary>{t('uxDetails')}</summary><p>{task.description}</p></details>{/if}<div class="checklist">{#each task.checklist??[] as item,index}<label><input type="checkbox" checked={item.done} disabled={!editable||busy} onchange={(e)=>update(task,task.checklist.map((old:any,i:number)=>i===index?{...old,done:e.currentTarget.checked}:old))}/><span>{item.label}</span></label>{/each}</div><div class="task-footer"><small>{task.due_at?new Intl.DateTimeFormat(lang,{dateStyle:'short',timeStyle:'short',timeZone:timezone}).format(new Date(task.due_at)):t('uxNoDate')}</small>{#if editable&&task.status!=='done'}<button class="complete" aria-label={t('done')+' · '+task.title} disabled={busy} onclick={()=>update(task,task.checklist,'done')}><Icon name="check" size={15}/>{t('done')}</button>{/if}</div></article>{:else}<p class="empty-state">{t('uxNoResults')}</p>{/each}</div>{#if tasks.length>limit}<button class="secondary more" onclick={()=>limit+=6}>{t('uxMore')} ({tasks.length-limit})</button>{/if}{#if message}<p class="notice" role="status">{message}</p>{/if}</section>
<style>.task-header{display:flex;justify-content:space-between;align-items:center;gap:20px}.task-header h2{display:flex;align-items:center;gap:9px;margin:0}.task-header input{min-height:38px;font-size:12px;width:240px}.task-filters{display:flex;gap:5px;margin:18px 0}.task-filters button{color:var(--muted);background:none;min-height:34px;font-size:11px;padding:7px 11px}.task-filters button.selected{background:var(--tint);color:var(--brand)}.task-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:14px}.task-grid article{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:11px;padding:18px;min-width:0;background:#fff}.task-grid article.overdue{border-top:3px solid #dab773}.task-meta{display:flex;align-items:center;justify-content:space-between;gap:10px}.due{font-size:10px;display:flex;align-items:center;gap:4px;color:#93610b}h3{margin:13px 0 10px;font-size:13px;line-height:1.5}.description summary{padding:3px 0;min-height:30px;font-size:11px;color:var(--muted)}.description p{font-size:12px;color:var(--muted)}.checklist{margin-top:10px;margin-bottom:16px}.checklist label{display:flex;gap:9px;align-items:flex-start;margin:9px 0;font-size:11px;line-height:1.5;color:#566d61}.checklist input{flex-shrink:0;margin-top:1px}.task-footer{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:auto;padding-top:14px;border-top:1px solid #eef3ef}.task-footer small{font-size:10px;color:var(--muted)}.complete{display:flex;align-items:center;gap:5px;font-size:10px;min-height:34px;background:var(--tint);color:var(--brand);padding:6px 9px}.complete:hover{background:#d8edde}.more{margin-top:18px;font-size:12px}@media(max-width:640px){.task-header{align-items:flex-start;flex-direction:column;gap:12px}.task-header label,.task-header input{width:100%}.task-grid{grid-template-columns:1fr}}
</style>
